    private void EffacerLesLignes()
    {
        int compteDansLigne = default;
        List<object> nouveauPlateau = default;
        for (var ligne = 0; ligne <= 19; ligne++)
        {
            compteDansLigne = 0;
            foreach (var cellule in plateau)
            {
                if ((((PointF)cellule).Y == ligne))
                {
                    compteDansLigne = (compteDansLigne + 1);
                }
            }
            if ((compteDansLigne >= 10))
            {
                nouveauPlateau = new List<object>();
                foreach (var cellule in plateau)
                {
                    if ((((PointF)cellule).Y != ligne))
                    {
                        if ((((PointF)cellule).Y < ligne))
                        {
                            nouveauPlateau.Add(new PointF((float)(((PointF)cellule).X), (float)((((PointF)cellule).Y + 1))));
                        }
                        if ((((PointF)cellule).Y > ligne))
                        {
                            nouveauPlateau.Add(new PointF((float)(((PointF)cellule).X), (float)(((PointF)cellule).Y)));
                        }
                    }
                }
                plateau = nouveauPlateau;
                score = (score + 100);
                PlayTone((int)(800), (int)(100));
            }
        }
    }

